const SoftwareToolsCore={
 page(text,start=0,count=8000){const body=String(text),from=Math.min(body.length,Math.max(0,Math.floor(Number(start)||0))),size=Math.max(256,Math.min(18000,Math.floor(Number(count)||8000))),end=Math.min(body.length,from+size);return{text:body.slice(from,end),range:{start:from,end,totalCharacters:body.length},nextStart:end<body.length?end:null,complete:end>=body.length}},
 observations(steps,budget=85000){const encoder=new TextEncoder(),out=steps.map(s=>({id:s.id,name:s.name,status:s.status,summary:String(s.error||s.result?.message||s.label||'').slice(0,300)}));for(let i=steps.length-1;i>=0;i--){const s=steps[i];if(!s.result&&!s.checkpoint?.runId)continue;const body=JSON.stringify(AssistantCore.public(s.result||{runId:s.checkpoint.runId,notice:'原流程保留，请读取实际状态'})),cost=encoder.encode(JSON.stringify(body)).length;if(cost>budget||body.length>30000)continue;out[i].resultJson=body;budget-=cost;}return out}
};
/* SOFTWARE_TOOLS_CORE_END */
CAT.find(c=>c[0]==='assistant.read')[1]='实际读取文件正文，返回内容供后续分析，可分页，不按文件名猜测';
CAT.find(c=>c[0]==='assistant.read')[2]='fileId,start?,count?';
CAT.push(['assistant.inspect','查看软件实际状态或指定项目/流程内容；kind为workspace/project/run/connections/library/skill/auth','kind,id?,start?,count?'],['assistant.write','将实际分析或生成的文本保存为软件内文件，可撤销；支持md/txt/csv/json','name,text,projectId?,boardId?'],['window.update','移动/缩放/收拢现有浮层，保留未点名字段','windowId,x?,y?,width?,height?,collapsed?']);
CAT.push(['auth.focus','聚焦本软件任务的本人验证界面，不扩大许可','taskId'],['auth.resume','本人已完成验证后接续本软件任务','taskId'],['auth.cancel','取消本软件的授权接力任务','taskId'],['library.refresh','开始实际检查工具目录来源，状态可查询',''],['library.stop','停止正在进行的目录更新并保留有效目录','']);
async function operatorRead(a,signal){const f=fnd(state.files,a.fileId,'文件');if(DF.reading.has(f.id)){while(DF.reading.has(f.id))await asDelay(150,signal)}else await dmRead(f);signal.throwIfAborted();const d=DF.records.get(f.id);if(d?.status!=='ready')throw new Error(d?.error||'正文读取尚未成功');const body=d.segments.map(s=>'【'+s.location+'】\n'+s.text).join('\n\n');return AssistantCore.public({fileId:f.id,name:f.name,...SoftwareToolsCore.page(body,a.start,a.count),message:'已读取实际正文；'+(body.length>18000?'长文件可继续分页或交给团队完整处理':'可依据正文继续分析')})}
async function operatorInspect(a,signal){let value,ref={};switch(a.kind){
 case'workspace':value={activeBoardId:state.activeBoard,roomId:state.room,selected:state.sel,boards:state.boards.map(b=>({id:b.id,name:b.name})),projects:state.projects.map(p=>({id:p.id,boardId:p.boardId,name:p.name})),links:state.links,clusters:state.clusters,files:state.files.map(({id,pid,boardId,name})=>({id,pid,boardId,name})),windows:dmWindows().filter(el=>el.getBoundingClientRect().width).map(el=>({id:dmWindowKey(el),rect:el.getBoundingClientRect().toJSON(),collapsed:el.classList.contains('dm-collapsed')}))};break;
 case'project':{const p=rp(a.id);ref={projectId:p.id};value={id:p.id,name:p.name,goal:p.summary,coordinator:p.coordinator,members:p.members,draft:p.ui.composerDraft,messages:p.msgs.map(({id,from,to,text,st})=>({id,from,to,text,status:st})),artifacts:p.artifacts,files:state.files.filter(f=>f.pid===p.id).map(({id,name})=>({id,name})),incoming:state.deliveries.filter(d=>d.to===p.id),notes:state.notes.filter(n=>n.pid===p.id).map(({id,text})=>({id,text}))};break;}
 case'run':{const r=await cpApi('get',{id:a.id});cpApply(r);ref={runId:r.id};value={id:r.id,status:r.status,error:r.error,result:r.result,steps:r.steps.map(s=>({id:s.id,projectId:s.projectId,member:s.member.name,model:cpStepTarget(r,s)?.model,phase:s.phase,status:s.status,text:s.text,error:s.error})),deliveries:r.deliveries};break;}
 case'connections':{const r=await mcApi('list');value={profiles:r.profiles.map(({id,name,vendor,configured,defaultModel,status})=>({id,name,vendor,configured,defaultModel,status})),vendors:r.vendors,warning:r.warning};break;}
 case'skill':{const g=await sbApi('guide',{id:a.id},signal);value={id:g.id,title:g.title,source:g.source,license:g.licenseText,bodyHash:g.bodyHash,referenceOnly:g.referenceOnly,body:g.body};break;}
 case'library':value=await sbApi('status',{},signal);break;
 case'auth':{const r=await fetch('/api/studio/auth',{signal});if(!r.ok)throw new Error('授权状态暂不可读');value=await r.json();break;}
 default:throw new Error('请选择软件、项目、流程、模型连接、能力库或授权状态');
 }signal.throwIfAborted();const body=JSON.stringify(AssistantCore.public(value),null,2);return{...ref,kind:a.kind,...SoftwareToolsCore.page(body,a.start,a.count),message:'已查看实际'+({workspace:'软件状态',project:'项目内容',run:'协作结果',connections:'连接元数据',library:'能力库状态',skill:'Skill实际正文',auth:'授权状态'})[a.kind]};}
async function operatorWrite(a,ctx){if(ctx.step.checkpoint?.fileId&&state.files.some(f=>f.id===ctx.step.checkpoint.fileId))return{fileId:ctx.step.checkpoint.fileId,message:'文件已保存，未重复创建'};const name=String(a.name||'');if(!/^[^/\\]{1,160}\.(?:md|txt|csv|json)$/i.test(name))throw new Error('文件名需为md/txt/csv/json，不包含路径');if(typeof a.text!=='string'||!a.text.length||a.text.length>100000)throw new Error('请提供1—100000字的实际文件正文');const p=a.projectId?rp(a.projectId):null,bid=p?.boardId||a.boardId||state.activeBoard;if(!state.boards.some(b=>b.id===bid))throw new Error('目标画板不存在');ctx.signal.throwIfAborted();const before=new Set(state.files.map(f=>f.id));await addFiles([new File([a.text],name,{type:'text/plain;charset=utf-8'})],p?{pid:p.id,x:p.space.x-p.space.r,y:p.space.y+p.space.r+36}:{boardId:bid,x:40,y:160});const f=state.files.find(f=>!before.has(f.id));if(!f)throw new Error('没有观察到已保存文件');if(f.boardId!==bid){f.boardId=bid;save()}ctx.step.checkpoint={...(ctx.step.checkpoint||{}),fileId:f.id};asPersist();return{fileId:f.id,projectId:p?.id,boardId:bid,name:f.name,characters:a.text.length,message:'已实际保存「'+f.name+'」'+(p?'到「'+p.name+'」':'到画板')+'，可展开查看或撤销'};}
function operatorWindow(a){const el=dmWindows().find(el=>dmWindowKey(el)===a.windowId&&el.getBoundingClientRect().width);if(!el)throw new Error('请先打开对应窗口');const r=el.getBoundingClientRect(),before=state.prefs.windowBoxes[a.windowId]||{x:r.x,y:r.y,w:r.width,h:r.height},box={...before};for(const [key,dest]of Object.entries({x:'x',y:'y',width:'w',height:'h'}))if(a[key]!==undefined){if(!Number.isFinite(Number(a[key])))throw new Error('窗口位置和尺寸必须为数字');box[dest]=Number(a[key])}if(a.collapsed!==undefined){if(typeof a.collapsed!=='boolean')throw new Error('收拢开关需为布尔值');box.collapsed=a.collapsed}pushUndo();state.prefs.windowBoxes[a.windowId]=box;save();dmDecorate();return{windowId:a.windowId,message:'已调整窗口，可撤销'};}
async function operatorStop(name,a,signal){const group=name==='group.stop'?fnd(state.groups,a.groupId,'跨项目组'):null,p=group?null:rp(a.projectId),members=group?[group.coordinator]:name==='run.stopAll'?[p.coordinator,...p.members]:[mem(p,a.memberId)],r=group?[...CP.runs.values()].filter(r=>r.group?.id===group.id).at(-1):cpCurrent(p.id);if(p)CP.preparing.get(p.id)?.ac.abort();for(const m of members){liveTurns.get(m.id)?.ac.abort();pendingTurns.get(m.id)?.ac.abort();halt(m.id)}let stopped;if(r&&cpLive(r)){stopped=await cpApi(name==='run.stop'||name==='models.stop'?'pause':'stop',{id:r.id,...(a.memberId?{projectId:p.id,memberId:a.memberId}:{})});cpApply(stopped)}const until=Date.now()+10000;while(members.some(m=>liveTurns.has(m.id)||pendingTurns.has(m.id))){if(Date.now()>until)throw new Error('停止请求已发出，仍在等待输出落地，请检查实际状态');await asDelay(60,signal)}return{...(p?{projectId:p.id}:{}),...(r?{runId:r.id}:{}),message:stopped?'实际流程已'+(stopped.status==='paused'?'暂停':'停止')+'，已有输出保留':'指定成员已停止，已有输出保留'};}
const operatorInvokeBase=asInvoke;asInvoke=async function(name,a,ctx){let r;if(name==='assistant.read')r=await operatorRead(a,ctx.signal);else if(name==='assistant.inspect')r=await operatorInspect(a,ctx.signal);else if(name==='assistant.write')r=await operatorWrite(a,ctx);else if(name==='window.update')r=operatorWindow(a);else if(['run.stop','run.stopAll','group.stop','models.stop'].includes(name))r=await operatorStop(name,a,ctx.signal);else if(['auth.focus','auth.resume','auth.cancel'].includes(name)){const response=await fetch('/api/studio/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:name.split('.')[1],taskId:a.taskId})});r=await response.json();if(!response.ok)throw new Error(r.error||'接力操作尚未完成');r.message='授权服务实际回执：'+(r.status||r.requested);}else if(name==='library.refresh'||name==='library.stop'){r=await sbApi(name==='library.refresh'?'refresh':'cancel-refresh',{},ctx.signal);r.message='目录更新实际状态：'+(r.update?.state||'待检查');}else return operatorInvokeBase(name,a,ctx);return AssistantCore.public(r)};
async function asPlanRound(s,signal){const context=AssistantCore.public({...asContext(),execution:SoftwareToolsCore.observations(s.steps),followups:s.followups||[],nextStep:s.steps.length+1,observation:{page:state.room?'project-chat':'canvas',tool,panel:panK||null,lastError:s.reason||'',runs:[...CP.runs.values()].slice(-80).map(r=>({id:r.id,boardId:r.boardId,status:r.status,projectIds:r.projects.map(p=>p.data.id)}))}});const r=await fetch('/api/studio/assistant',{method:'POST',headers:{'Content-Type':'application/json'},signal,body:JSON.stringify({message:s.request,context,capabilities:CAT.map(c=>({name:c[0],description:c[1],params:c[2]})),...(s.binding||state.prefs.assistantBinding?{binding:s.binding||state.prefs.assistantBinding}:{})})});const d=await r.json();if(!r.ok)throw new Error(d.error||'操作模型分析未完成');return d;}
async function asSteer(text){const s=asSession();if(!s||!s.operator)return asAsk(text);if(s.steering)return;s.steering=true;try{asPause();while(AS.ac)await new Promise(r=>setTimeout(r,30));s.followups=s.followups||[];s.followups.push(text);if(s.followups.length>20)s.followups.shift();for(let i=s.cursor||0;i<s.steps.length;i++)if(s.steps[i].status!=='done')s.steps[i].status='replanned';s.cursor=s.steps.length;s.question='';s.finalReply='';s.status='ready';AS.draft='';asPersist();void asExecute(s)}finally{s.steering=false}}
for(const name of ['assistant.inspect','assistant.write','window.update','auth.focus','auth.resume','auth.cancel','library.refresh','library.stop'])ACT[name]=a=>{const s={id:'as'+uid(),boardId:state.activeBoard,request:CAT.find(c=>c[0]===name)[1],steps:[{id:'s1',name,label:CAT.find(c=>c[0]===name)[1],args:a,status:'pending',effect:'local'}],cursor:0,status:'ready',createdAt:Date.now()};state.assistantSessions.push(s);AS.current=s.id;$('#guide').classList.add('o');void asExecute(s);return'已交给操作助手，查看实际结果'};
